ALPHABETS = {
    "только цифры": 10,
    "строчные буквы": 26,
    "буквы и цифры": 62,
    "с символами": 95,
}
GUESSES_PER_SECOND = 10_000_000_000     # современная видеокарта

def years(alphabet, length):
    combinations = alphabet ** length
    seconds = combinations / GUESSES_PER_SECOND
    return seconds / 60 / 60 / 24 / 365

for name, size in ALPHABETS.items():
    for length in (8, 12, 16):
        y = years(size, length)
        if y < 1 / 365:
            verdict = "меньше суток"
        elif y < 1:
            verdict = f"{y * 365:.0f} дней"
        else:
            verdict = f"{y:,.0f} лет"
        print(f"{name:15} длина {length:2} -> {verdict}")

